import argparse
import csv
import json
import sys
from datetime import datetime
from decimal import Decimal, ROUND_HALF_UP


def parse_timestamp(ts: str) -> datetime:
    """Parse an ISO‑8601 timestamp with timezone offset into a tz‑aware datetime."""
    # datetime.fromisoformat handles offsets like +02:00 and -05:00
    return datetime.fromisoformat(ts)


def reconcile(input_file: str):
    # First pass: read all rows and keep the latest entry for each tx_id
    latest_tx = {}
    with open(input_file, "r", newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            tx_id = row["tx_id"].strip()
            try:
                ts = parse_timestamp(row["timestamp"].strip())
            except Exception:
                # If timestamp is malformed, skip this row entirely
                continue
            # If we have not seen this tx_id or this row is newer, store it
            if tx_id not in latest_tx or ts > latest_tx[tx_id]["_ts"]:
                # Store the row together with its parsed timestamp for later comparison
                latest_tx[tx_id] = {**row, "_ts": ts}

    total_valid_amount = Decimal('0')
    valid_count = 0
    failed_count = 0

    for row in latest_tx.values():
        status = row["status"].strip().upper()
        amount_str = row["amount"].strip()
        # Use Decimal for amount; any invalid amount is treated as 0
        try:
            amount = Decimal(amount_str)
        except Exception:
            amount = Decimal('0')

        if status == "VALID":
            total_valid_amount += amount
            valid_count += 1
        else:
            failed_count += 1

    # Round total to two decimal places using ROUND_HALF_UP (standard financial rounding)
    total_valid_amount = total_valid_amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

    return {
        "total_valid_amount": float(total_valid_amount),
        "valid_count": valid_count,
        "failed_count": failed_count,
    }


def main():
    parser = argparse.ArgumentParser(description="Payment transaction reconciliation")
    parser.add_argument("--input", required=True, help="Path to the transactions CSV file")
    args = parser.parse_args()

    try:
        result = reconcile(args.input)
        print(json.dumps(result, indent=2))
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()
EOF
